std::vector<Halfedge*> boundary_edges;
for (auto it = poly.halfedges().begin(); it != poly.halfedges().end(); ++it) {
    if (it->opposite()->face() == nullptr) {
        boundary_edges.push_back(&(*it));
    }
}

while (!boundary_edges.empty()) {
    std::vector<Halfedge*> loop;
    std::set<Halfedge*> visited;

    if (boundary_edges.empty()) break;

    Halfedge* start = boundary_edges.back();
    boundary_edges.pop_back();

    Halfedge* curr = start;
    do {
        loop.push_back(curr);
        visited.insert(curr);
        curr = curr->opposite()->next();
    } while (curr != start && curr != nullptr);

    // Remove this loop's edges from the global boundary list
    for (auto it = boundary_edges.begin(); it != boundary_edges.end(); ) {
        if (visited.count(*it)) it = boundary_edges.erase(it);
        else ++it;
    }

    if (loop.size() < 3) continue;

    // Simple fan triangulation from the first vertex of the loop
    Vertex* v0 = loop[0]->vertex();
    for (size_t i = 1; i < loop.size() - 1; ++i) {
        Vertex* v1 = loop[i]->opposite()->vertex();
        Vertex* v2 = loop[i+1]->opposite()->vertex();

        // Create a new face by adding edges between v0, v1, and v2
        // This assumes the Polyhedron class has a method to add a face from vertices
        poly.addFace({v0, v1, v2});
    }
}
// END_CODE

